// backoff.test.ts: rode com `node --test` (acha os *.test.ts sozinho)
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';

function calcularBackoff(base: number, tentativa: number): number {
  return base * 2 ** (tentativa - 1);
}

describe('calcularBackoff', () => {
  test('dobra a cada tentativa', () => {
    assert.equal(calcularBackoff(100, 1), 100);
    assert.equal(calcularBackoff(100, 2), 200);
    assert.equal(calcularBackoff(100, 3), 400);
  });

  test('deepEqual compara estrutura, não referência', () => {
    assert.deepEqual([1, 2, 3].map((t) => calcularBackoff(10, t)), [10, 20, 40]);
  });

  test('rejects verifica código async que deve falhar', async () => {
    await assert.rejects(Promise.reject(new Error('timeout no SMTP')), /timeout/);
  });
});

import { UnrecoverableError } from 'bullmq';
import assert from 'node:assert/strict';
import { mock, test } from 'node:test';

// A regra de negócio recebe as dependências por parâmetro: testável sem Redis nem SMTP
interface Smtp { send(to: string, subject: string): Promise<string> }

export async function enviarEmail(data: { to: string; subject: string }, smtp: Smtp) {
  if (!data.to.includes('@')) throw new UnrecoverableError(`endereço inválido: ${data.to}`);
  return { messageId: await smtp.send(data.to, data.subject) };
}
// No worker, o handler só repassa: 'enviar-email': (job) => enviarEmail(job.data, smtpReal)

test('envia e devolve o messageId', async () => {
  const send = mock.fn<Smtp['send']>(async () => 'msg-1');
  const resultado = await enviarEmail({ to: 'ana@ex.com', subject: 'Oi' }, { send });

  assert.deepEqual(resultado, { messageId: 'msg-1' });
  assert.equal(send.mock.callCount(), 1);
  assert.deepEqual(send.mock.calls[0]?.arguments, ['ana@ex.com', 'Oi']);
});

test('endereço inválido nem chama o SMTP, e não terá retry', async () => {
  const send = mock.fn<Smtp['send']>(async () => 'nunca');
  await assert.rejects(enviarEmail({ to: 'sem-arroba', subject: 'Oi' }, { send }), UnrecoverableError);
  assert.equal(send.mock.callCount(), 0);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';

// Código a testar: tenta de novo com backoff exponencial
async function comRetry<T>(fn: () => Promise<T>, tentativas: number, baseMs: number): Promise<T> {
  for (let i = 1; ; i++) {
    try {
      return await fn();
    } catch (err) {
      if (i >= tentativas) throw err;
      await new Promise((resolve) => setTimeout(resolve, baseMs * 2 ** (i - 1)));
    }
  }
}

// Deixa as Promises pendentes andarem (setImmediate continua real)
const flush = () => new Promise((resolve) => setImmediate(resolve));

test('espera 1s e depois 2s entre as tentativas, sem esperar de verdade', async (t) => {
  t.mock.timers.enable({ apis: ['setTimeout'] }); // relógio falso só neste teste

  let chamadas = 0;
  const instavel = async () => {
    chamadas++;
    if (chamadas < 3) throw new Error('falhou');
    return 'ok';
  };

  const resultado = comRetry(instavel, 3, 1_000);

  await flush();
  assert.equal(chamadas, 1);   // 1ª tentativa falhou; agora espera 1s
  t.mock.timers.tick(999);
  await flush();
  assert.equal(chamadas, 1);   // ainda não deu 1s
  t.mock.timers.tick(1);
  await flush();
  assert.equal(chamadas, 2);   // 2ª tentativa falhou; agora espera 2s
  t.mock.timers.tick(2_000);
  assert.equal(await resultado, 'ok');
  assert.equal(chamadas, 3);   // o teste levou milissegundos, não 3 segundos
});

import { Queue, QueueEvents, Worker } from 'bullmq';
import { Redis } from 'ioredis';
import assert from 'node:assert/strict';
import { after, before, test } from 'node:test';

// Precisa de um Redis de teste rodando (ex.: docker compose up -d redis)
const nomeFila = `teste-${process.pid}-${Date.now()}`; // fila única: execuções não se atropelam
const conexoes: Redis[] = [];
const conectar = () => {
  const c = new Redis({ maxRetriesPerRequest: null });
  conexoes.push(c);
  return c;
};

let queue: Queue;
let events: QueueEvents;
let worker: Worker;

before(async () => {
  queue = new Queue(nomeFila, { connection: conectar() });
  events = new QueueEvents(nomeFila, { connection: conectar() });
  worker = new Worker(nomeFila, async (job) => ({ dobro: job.data.n * 2 }), { connection: conectar() });
  await events.waitUntilReady();
});

after(async () => {
  await worker.close();
  await events.close();
  await queue.obliterate({ force: true }); // não deixa lixo no Redis
  await queue.close();
  await Promise.all(conexoes.map((c) => c.quit()));
});

test('o job sai do produtor, passa pelo worker e volta com o resultado', async () => {
  const job = await queue.add('dobrar', { n: 21 });
  const resultado = await job.waitUntilFinished(events, 5_000);
  assert.deepEqual(resultado, { dobro: 42 });
});

